def build_agent(sandbox):
    agent = sandbox.get_agent_body()
    agent.userData = {
        'unlock_steps': 0,
        'exit_steps': 0,
        'is_unlocked': False
    }
    return agent

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_agent_position()
    x, y = pos
    vel = sandbox.get_agent_velocity()
    vx, vy = vel

    state = agent_body.userData

    # Navigation logic
    if not state['is_unlocked']:
        # Check if in unlock zone
        if 5.0 <= x <= 10.0:
            # Apply unlock force
            if abs(vx) < 100.0:
                fx_unlock = -35.0
                sandbox.apply_agent_force(fx_unlock, 0.0)
                state['unlock_steps'] += 1
                # Check if unlock condition is met
                if state['unlock_steps'] >= 5:
                    state['is_unlocked'] = True
                    state['unlock_steps'] = 0
            else:
                state['unlock_steps'] = 0
        else:
            # Apply navigation force
            front, up, down = sandbox.get_whisker_readings()
            if front < 3.0:  # Wall in front, move backward
                fx = -10.0
            else:
                fx = 10.0  # Move forward
            sandbox.apply_agent_force(fx, 0.0)
    else:
        # After unlocking, check exit zone
        if x >= 15.0:
            # Apply zero force to hold in exit zone
            sandbox.apply_agent_force(0.0, 0.0)
            state['exit_steps'] += 1
            if state['exit_steps'] >= 5:
                # Task completed
                pass
        else:
            # Move forward to exit zone
            sandbox.apply_agent_force(10.0, 0.0)
            state['exit_steps'] = 0

